  useEffect(() => {
    // 1. Check for Portal Parameter in URL (Deep Linking/Isolation)
    const params = new URLSearchParams(window.location.search);
    const portalParam = params.get('portal')?.toUpperCase() as UserRole;

    if (portalParam && ['MR', 'COMPANY_ADMIN', 'ADMIN', 'SECURITY', 'SUPER_ADMIN'].includes(portalParam)) {
      setActivePortal(portalParam);
      setIsLockedPortal(true);
    }

    // 2. Check Session
    const session = storageService.getCurrentUser();
    if (session) { 
      // Ensure session role matches locked portal if applicable
      if (portalParam && session.role !== portalParam) {
        storageService.clearSession();
      } else {
        setUser(session); 
        setActivePortal(session.role);
        setView('DASHBOARD'); 
      }
    }

    // 3. Automation Logic (Lottery & Expiry)
    const automationInterval = setInterval(() => {
      const now = new Date();
      const today = now.toLocaleDateString('en-CA');
      const currentTimeStr = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
      const currentTimeNum = now.getHours() * 100 + now.getMinutes();
      const hospitals = storageService.getHospitals();

      // Auto Pass Expiration
      const allPasses = storageService.getPasses();
      let hasPassChanges = false;
      const updatedPasses = allPasses.map(p => {
        if (p.passDate === today && p.entryStatus !== 'expired') {
          let shouldExpire = false;
          if (p.session === 'MORNING' && currentTimeNum >= 1300) shouldExpire = true;
          if ((p.session === 'EVENING' || p.session === 'FULL_DAY') && currentTimeNum >= 2000) shouldExpire = true;
          if (shouldExpire) { hasPassChanges = true; return { ...p, entryStatus: 'expired' as const }; }
        }
        return p;
      });
      if (hasPassChanges) storageService.savePasses(updatedPasses);

      // Auto Lottery
      hospitals.forEach(hosp => {
        if (!hosp.isActive || !hosp.autoLotteryEnabled) return;
        (['MORNING', 'EVENING', 'FULL_DAY'] as SessionType[]).forEach(sess => {
          if (hosp.autoLotteryEnabled?.[sess] && hosp.autoLotteryTimes?.[sess] === currentTimeStr) {
            const logKey = `${hosp.id}-${today}-${sess}`;
            if (!autoRunLogs.current.has(logKey)) {
              const result = lotteryService.runLottery(hosp.id, sess);
              if (result.success || result.message === "No applications found.") autoRunLogs.current.add(logKey);
            }
          }
        });
      });
    }, 15000);

    return () => clearInterval(automationInterval);
