      const mrs = storageService.getMRs();
      const existing = mrs.find(m => m.loginId === mobile);
      if (existing) {
        if (existing.status === 'suspended') { showFeedback("Account suspended.", 'error'); return; }
        if (existing.password && existing.password !== password) { showFeedback("Invalid credentials.", 'error'); return; }
        const u: AuthUser = { id: existing.id, fullName: existing.fullName, role: 'MR', companyName: existing.companyName, loginId: existing.loginId, mobileNumber: existing.mobileNumber };
        storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
      } else { showFeedback("Representative not found.", 'error'); }
    } else if (role === 'COMPANY_ADMIN') {
      const companies = storageService.getCompanies();
      const found = companies.find(c => c.adminMobile === mobile);
      if (found && found.adminPassword === password) {
        if (!found.isActive) { showFeedback("Company deactivated.", 'error'); return; }
        const u: AuthUser = { id: found.id, role: 'COMPANY_ADMIN', fullName: `${found.name} Admin`, companyId: found.id };
        storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
      } else { showFeedback("Invalid credentials.", 'error'); }
    } else if (role === 'ADMIN' || role === 'SECURITY') {
      const hospitalUsers = storageService.getHospitalUsers();
      const found = hospitalUsers.find(u => u.mobileNumber === mobile && u.role === role);
      if (found && found.password === password) {
        const u: AuthUser = { id: found.id, role: found.role, fullName: found.fullName, hospitalId: found.hospitalId, mobileNumber: found.mobileNumber };
        storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
