              <span className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">Powered by</span>
              <div className="flex items-center gap-1.5 bg-white px-4 py-2 rounded-2xl border border-slate-200 shadow-xl">
                <Zap className="h-4 w-4 text-indigo-600" />
                <span className="text-sm font-black text-slate-900 tracking-tighter lowercase">dren</span>
              </div>
            </div>
            <p className="text-[9px] font-bold text-slate-500 uppercase tracking-widest">Professional Field Intelligence</p>
          </div>
        </div>
      </div>
    );
  }

  // Portal Login View
  if (view === 'LOGIN') {
    return (
      <FeedbackContext.Provider value={{ showFeedback }}>
