              <ArrowRight className="h-4 w-4 rotate-180" /> BACK TO PORTAL SELECTION
            </button>
          )}

          <div className="bg-white w-full max-w-md rounded-[2.5rem] shadow-2xl shadow-slate-200/50 overflow-hidden border border-slate-100">
            <div className={`p-10 text-center border-b border-slate-50 ${activePortal === 'SUPER_ADMIN' ? 'bg-slate-900 text-white' : 'bg-white text-slate-900'}`}>
              <div className={`w-16 h-16 rounded-2xl flex items-center justify-center mx-auto mb-6 shadow-lg ${
                activePortal === 'MR' ? 'bg-blue-600' : 
                activePortal === 'ADMIN' ? 'bg-indigo-600' : 
                activePortal === 'SECURITY' ? 'bg-emerald-600' : 
                activePortal === 'COMPANY_ADMIN' ? 'bg-violet-600' : 'bg-slate-700'
