                 activePortal === 'ADMIN' ? <Building2 className="h-8 w-8 text-white"/> : 
                 activePortal === 'SECURITY' ? <ShieldCheck className="h-8 w-8 text-white"/> : 
                 activePortal === 'COMPANY_ADMIN' ? <Briefcase className="h-8 w-8 text-white"/> : <Crown className="h-8 w-8 text-white"/>}
              </div>
              <h2 className="text-2xl font-black tracking-tight uppercase">{activePortal?.replace('_', ' ')} LOGIN</h2>
              <p className={`text-xs font-bold mt-1 ${activePortal === 'SUPER_ADMIN' ? 'text-slate-400' : 'text-slate-400'}`}>Secure MedPass Entry Terminal</p>
            </div>

            <div className="p-10">
              <form onSubmit={handleLogin} className="space-y-6">
